{"code":"import pandas as pd
from datetime import datetime
from pathlib import Path
src_csv = Path('/utils/april-attendance-data.csv')
df = pd.read_csv(src_csv)
df.columns = [c.strip() for c in df.columns]
df = df.assign(**{c: df[c].astype(str).str.strip() for c in ['Name','Date','Clock-in','Clock-out']})

in_dt = pd.to_datetime(df['Date'] + ' ' + df['Clock-in'], format='%Y-%m-%d %H:%M')

def count_late(threshold_str):
    t = datetime.strptime(threshold_str, '%H:%M').time()
    return (in_dt.dt.time > t).sum()

for thr in ['09:15','09:10','09:05','09:00','08:55']:
    print(thr, count_late(thr))"}

